10	export const runScenario = (scenario: Scenario): ScenarioResult => {
11	  const results = scenario.steps.map((step) => {
12	    const items = step.items ?? [];
13	    const basePremium = items.length === 0 ? 0 : 110;
14	    return { premium: basePremium + PROCESSING_FEE };
15	  });
16	  return { results };
17	};
