input.new_string:
const premiumForItems = (items: Item[]): number =>
  items.length === 0 ? 0 : 110;

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => ({
    premium: premiumForItems(step.items ?? []) + PROCESSING_FEE,
  })),
});
